package test.com.mbeddr.mpsutil.common.util;

/*Generated by MPS */

import org.junit.jupiter.api.Test;
import org.apache.commons.lang3.mutable.MutableInt;
import java.util.function.Supplier;
import com.mbeddr.mpsutil.common.util.LazyInit;
import org.junit.Assert;

public class LazyInit_Test {
  @Test
  public void test_lazyInit() throws Exception {
    final MutableInt expensiveCount = new MutableInt(0);
    Supplier<Integer> supplier = LazyInit.lazy(() -> {
      // this is the expensive code
      expensiveCount.increment();
      return 777;
    });

    // execute first get(), should return 777, and expensive code should be executed exactly once
    int v1 = supplier.get();
    Assert.assertEquals(777, v1);
    Assert.assertEquals(1, (int) expensiveCount.getValue());

    // when executing get() again, it still should return 777, but without executing expensive code again
    int v2 = supplier.get();
    Assert.assertEquals(777, v2);
    Assert.assertEquals(1, (int) expensiveCount.getValue());
  }
}
